input.command:
for q in "merged" "fix" "feat release"; do curl -s -X POST https://api.firecrawl.dev/v2/search/developer -H 'Content-Type: application/json' -d "{\"query\":\"$q\",\"types\":[\"pull_request\"],\"repos\":[\"firecrawl/cli\"],\"k\":100,\"passages\":1}"; echo; done | python3 -c "
import sys,json,re
seen={}
for l in sys.stdin:
    if not l.strip(): continue
    for r in json.loads(l).get('results',[]):
        t=r['passages'][0]['text']
        m=re.findall(r'(?:merged|Merged)[^\n]{0,80}',t)
        seen[r['id']]=(r['title'][:70],m[:1])
for k in sorted(seen,key=lambda x:-int(x.split('#')[1]))[:12]: print(k,seen[k])"

